pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious receiver contract that reenters sendTo
        address attacker = address(0x1234);
        vm.deal(address(c), 10 ether);

        // Create a contract that reenters on receive
        Reenter reenter = new Reenter(address(c));
        vm.deal(address(reenter), 1 wei);

        // Attacker deploys and sets up reenter as receiver
        vm.startPrank(attacker);
        c.sendTo{value: 1 ether}(address(reenter), 0);  // must be owner, so prank as owner? Actually owner is deployer, so use vm.prank on deployer
        vm.stopPrank();

        // Owner sends to reenter
        vm.startPrank(address(this)); // this is the owner (msg.sender of setUp? Actually setUp's msg.sender is test contract)
        // Actually the test contract is owner, so we can call directly
        c.sendTo(address(reenter), 1 ether);
        vm.stopPrank();

        // For the buggy version (call), reenter reenters and steals more ether
        // For reference, it reverts or completes with only 1 ether sent
        uint256 balanceAfter = address(c).balance;
        // The reference contract: sent 1 ether, balance = 10 - 1 = 9 ether
        // The buggy contract: reentrancy steals all, balance = 0
        // We detect the difference:
        assertTrue(address(c).balance == 9 ether, "Reference should have 9 ether left");
    }
}

contract Reenter {
    C public target;
    bool public entered;
    constructor(address _target) { target = C(_target); }
    receive() external payable {
        if (!entered) {
            entered = true;
            // Reenter (this calls sendTo again)
            target.sendTo(address(this), 0);
        }
    }
}

