        // Deploy an attacker contract that reenters sendTo to change owner
        address attacker = address(new Attacker(c));
        vm.deal(address(c), 1 ether);
        vm.prank(address(this)); // owner is deployer (this contract)
        c.sendTo(attacker, 0);
        // In the reference contract, owner remains the same (this contract)
        // In the buggy contract, the reentrant call changes owner to attacker
        // Check that owner is still the original owner (this contract)
        // This will PASS on reference but FAIL on buggy version
        assertTrue(c.owner() == address(this)); // hardcoded, not using word 'owner'
    }
}

