pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a reentrant contract
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));
        // Fund the contract with 2 ether
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool success, ) = payable(address(c)).call{value: 2 ether}("");
        require(success, "funding failed");
        // Owner sends 1 ether to attacker; attacker reenters sendTo in receive()
        vm.deal(address(c), 2 ether); // ensure contract has 2 ether
        vm.prank(address(c.owner())); // owner call
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", address(attacker), 1 ether));
        // Check that reference contract keeps the second ether, buggy contract loses it
        bool buggyBehavior = (address(c).balance == 0); // bug: both sends succeed
        bool refBehavior = (address(c).balance > 0); // ref: second send fails
        assertTrue(refBehavior); // test passes on reference, fails on bug
    }
}

contract ReentrantAttacker {
    C target;
    bool entered;
    constructor(address _target) { target = C(_target); }
    receive() external payable {
        if (!entered) {
            entered = true;
            // Reenter sendTo with same amount to drain more
            (bool success, ) = address(target).call{value: msg.value}(abi.encodeWithSignature("sendTo(address,uint256)", address(this), msg.value));
            require(success, "reentrancy failed");
        }
    }
}

