pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ReentrancyReceiver {
    C public c;
    address public owner;
    uint public count;

    constructor(address _c) {
        c = C(_c);
        owner = msg.sender;
    }

    receive() external payable {
        if (count < 1) {
            count++;
            c.sendTo(owner, 10 ether);
        }
    }
}

contract InvMutTest is Test {
    C c;
    ReentrancyReceiver receiver;

    function setUp() public {
        c = new C();
        receiver = new ReentrancyReceiver(address(c));
        vm.deal(address(c), 10 ether);
        vm.deal(address(receiver), 0 ether);
    }

    function testRegression_property() public {
        vm.prank(address(c.owner()));
        c.sendTo(address(receiver), 10 ether);
        assertTrue(address(c).balance == 10 ether);
    }
}
